import Foundation

/// Candidate-extraction patterns for the deterministic layer.
///
/// These regexes are intentionally *loose* — they over-match on purpose and let
/// the ``Checksums`` validators reject the false positives. Each pattern is
/// paired with a neighbour rule that rejects a match glued to a character that
/// would make it part of a larger token (e.g. a 9-digit run inside a longer
/// number). We avoid regex lookbehind for engine portability and check
/// neighbours in code instead.
enum Patterns {

    /// What kind of character must *not* sit immediately before/after a match
    /// for it to count as a standalone token.
    enum Boundary {
        case digit          // reject if neighbour is 0-9
        case digitOrDot     // reject if neighbour is 0-9 or '.'
        case alphanumeric   // reject if neighbour is a letter or digit
        case hexOrColon     // reject if neighbour is a hex digit or ':'
        case emailChar      // reject if neighbour continues an address
        case dottedDecimal  // for IPv4: reject a digit, or a dot that continues the sequence

        /// - Parameters:
        ///   - ch: the character immediately adjacent to the match.
        ///   - beyond: the next character out (used for two-char lookahead), if any.
        func forbids(_ ch: Character, beyond: Character?) -> Bool {
            switch self {
            case .digit:
                return ch.isNumber
            case .digitOrDot:
                return ch.isNumber || ch == "."
            case .alphanumeric:
                return ch.isLetter || ch.isNumber
            case .hexOrColon:
                return ch == ":" || ch.isHexDigit
            case .emailChar:
                return ch.isLetter || ch.isNumber || "._%+-@".contains(ch)
            case .dottedDecimal:
                // A digit neighbour always continues the address. A dot only
                // continues it when another digit follows (so `1.2.3.4.5` is
                // rejected but `192.168.1.1.` at a sentence end is accepted).
                if ch.isNumber { return true }
                if ch == "." { return beyond?.isNumber ?? false }
                return false
            }
        }
    }

    static let email = #"[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}"#
    static let ipv4 = #"(?:[0-9]{1,3}\.){3}[0-9]{1,3}"#
    static let ipv6 = #"[0-9A-Fa-f]{0,4}(?::[0-9A-Fa-f]{0,4}){2,7}(?:%[A-Za-z0-9]+)?"#
    /// Compact IBAN: `NL91ABNA0417164300`.
    static let ibanCompact = #"[A-Za-z]{2}[0-9]{2}[A-Za-z0-9]{11,30}"#
    /// Grouped IBAN printed in blocks of four: `NL91 ABNA 0417 1643 00`.
    /// Interior groups are exactly four characters; only the final group may be
    /// shorter — this stops the match from swallowing a following word.
    static let ibanGrouped = #"[A-Za-z]{2}[0-9]{2}(?: [A-Za-z0-9]{4})+(?: [A-Za-z0-9]{1,3})?"#
    static let creditCard = #"[0-9](?:[ \-]?[0-9]){11,18}"#
    static let dutchID = #"[0-9]{8,10}"#
}
import Foundation

/// The deterministic PII layer: regex candidate extraction followed by checksum
/// / structural validation. Pure Swift, no model and no native dependencies.
///
/// Only candidates that pass their validator are emitted, each with an exact
/// character range, `confidence == 1.0`, and `source == .rules`.
struct DeterministicDetector {

    /// A single detection rule: pattern → validator → emitted type.
    private struct Rule {
        let type: PIIType
        let regex: Regex<AnyRegexOutput>
        let boundary: Patterns.Boundary
        let validate: @Sendable (Substring) -> Bool
    }

    private let rules: [Rule]

    /// Builds the detector, compiling only the rules for `allowedTypes`
    /// (or all rules when `nil`).
    init(allowedTypes: Set<PIIType>? = nil) {
        let all: [(PIIType, String, Patterns.Boundary, @Sendable (Substring) -> Bool)] = [
            (.email,        Patterns.email,        .emailChar,    { Checksums.email($0) }),
            (.iban,         Patterns.ibanCompact,  .alphanumeric, { Checksums.iban($0) }),
            (.iban,         Patterns.ibanGrouped,  .alphanumeric, { Checksums.iban($0) }),
            (.creditCard,   Patterns.creditCard,   .digit,        { Checksums.luhn($0) }),
            (.governmentID, Patterns.dutchID,    .digitOrDot,   { Checksums.dutchGovernmentID($0) }),
            (.ipAddress,    Patterns.ipv4,       .dottedDecimal, { Checksums.ipv4($0) }),
            (.ipAddress,    Patterns.ipv6,       .hexOrColon,   { Checksums.ipv6($0) }),
        ]
        rules = all.compactMap { type, pattern, boundary, validate in
            guard allowedTypes?.contains(type) ?? true else { return nil }
            // Patterns are authored as constants; a failure here is a programmer error.
            let regex = try! Regex(pattern)
            return Rule(type: type, regex: regex, boundary: boundary, validate: validate)
        }
    }

    /// Detects structured PII in `text`. Results are de-overlapped (longer, then
    /// earlier match wins) and returned in document order.
    func detect(in text: String) -> [PIIEntity] {
        var found: [PIIEntity] = []
        for rule in rules {
            for match in text.matches(of: rule.regex) {
                let range = match.range
                guard hasCleanBoundaries(text, range, rule.boundary) else { continue }
                let slice = text[range]
                guard rule.validate(slice) else { continue }
                found.append(
                    PIIEntity(
                        type: rule.type,
                        range: range,
                        text: slice,
                        confidence: 1.0,
                        source: .rules
                    )
                )
            }
        }
        return resolveOverlaps(found)
    }

    // MARK: - Boundaries

    /// Rejects a match whose immediate neighbours would make it part of a larger
    /// token (e.g. `4111...` inside a 20-digit string, or `1.2.3.4` inside
    /// `1.2.3.4.5`).
    private func hasCleanBoundaries(
        _ text: String,
        _ range: Range<String.Index>,
        _ boundary: Patterns.Boundary
    ) -> Bool {
        if range.lowerBound > text.startIndex {
            let beforeIndex = text.index(before: range.lowerBound)
            let before = text[beforeIndex]
            let beyond = beforeIndex > text.startIndex ? text[text.index(before: beforeIndex)] : nil
            if boundary.forbids(before, beyond: beyond) { return false }
        }
        if range.upperBound < text.endIndex {
            let after = text[range.upperBound]
            let afterNext = text.index(after: range.upperBound)
            let beyond = afterNext < text.endIndex ? text[afterNext] : nil
            if boundary.forbids(after, beyond: beyond) { return false }
        }
        return true
    }

    // MARK: - Overlap resolution

    /// Keeps the strongest non-overlapping set: sort by length (desc) then start
    /// (asc), then greedily accept matches that don't overlap an accepted one.
    private func resolveOverlaps(_ entities: [PIIEntity]) -> [PIIEntity] {
        let ordered = entities.sorted { lhs, rhs in
            if lhs.text.count != rhs.text.count { return lhs.text.count > rhs.text.count }
            return lhs.range.lowerBound < rhs.range.lowerBound
        }
        var accepted: [PIIEntity] = []
        for entity in ordered where !accepted.contains(where: { $0.range.overlaps(entity.range) }) {
            accepted.append(entity)
        }
        return accepted.sorted { $0.range.lowerBound < $1.range.lowerBound }
    }
}
import Foundation

/// Combines the neural and deterministic entity sets into one coherent,
/// non-overlapping list.
enum EntityMerger {

    /// Merges `model` and `rules` entities.
    ///
    /// - On an overlap, the higher-priority entity wins: rules if
    ///   `deterministicWins`, otherwise whichever has greater confidence.
    /// - `allowedTypes`, when non-nil, filters the final set.
    /// - The result is sorted in document order and free of overlaps.
    static func merge(
        model: [PIIEntity],
        rules: [PIIEntity],
        deterministicWins: Bool,
        allowedTypes: Set<PIIType>?
    ) -> [PIIEntity] {
        let candidates = (model + rules).filter { allowedTypes?.contains($0.type) ?? true }

        // Higher priority sorts first: preferred source, then longer span, then
        // higher confidence, then earlier start (stable, deterministic order).
        let ordered = candidates.sorted { lhs, rhs in
            let lhsPreferred = deterministicWins && lhs.source == .rules
            let rhsPreferred = deterministicWins && rhs.source == .rules
            if lhsPreferred != rhsPreferred { return lhsPreferred }
            if lhs.text.count != rhs.text.count { return lhs.text.count > rhs.text.count }
            if lhs.confidence != rhs.confidence { return lhs.confidence > rhs.confidence }
            return lhs.range.lowerBound < rhs.range.lowerBound
        }

        var accepted: [PIIEntity] = []
        for entity in ordered where !accepted.contains(where: { $0.range.overlaps(entity.range) }) {
            accepted.append(entity)
        }
        return accepted.sorted { $0.range.lowerBound < $1.range.lowerBound }
    }
}
